-- HRMS Phase 2 attendance and leave.
create table hr_attendance_record(id bigint generated by default as identity primary key,employee_id bigint not null references hr_employee(id) on delete restrict,work_date date not null,attendance_status varchar(16) not null check(attendance_status in ('PRESENT','ABSENT','HALF_DAY','REMOTE','ON_LEAVE','HOLIDAY')),check_in_at timestamptz,check_out_at timestamptz,notes varchar(500),recorded_by_staff_id bigint references staff_account(id) on delete set null,updated_by_staff_id bigint references staff_account(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(employee_id,work_date),check(check_out_at is null or check_in_at is not null),check(check_out_at is null or check_out_at>check_in_at),check(attendance_status not in ('ABSENT','ON_LEAVE','HOLIDAY') or (check_in_at is null and check_out_at is null)));
create index idx_hr_attendance_date_status on hr_attendance_record(work_date,attendance_status);
create index idx_hr_attendance_employee_date on hr_attendance_record(employee_id,work_date desc);
create table hr_leave_type(code varchar(32) primary key,display_name varchar(80) not null unique,paid boolean not null default true,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into hr_leave_type(code,display_name,paid) values ('CASUAL','Casual leave',true),('SICK','Sick leave',true),('EARNED','Earned leave',true),('UNPAID','Leave without pay',false),('COMP_OFF','Compensatory off',true) on conflict(code) do nothing;
create table hr_leave_request(id bigint generated by default as identity primary key,public_id uuid not null unique default gen_random_uuid(),employee_id bigint not null references hr_employee(id) on delete restrict,leave_type_code varchar(32) not null references hr_leave_type(code),start_date date not null,end_date date not null,requested_days numeric(5,2) not null check(requested_days>0 and requested_days<=366),reason varchar(1000) not null,request_status varchar(16) not null default 'PENDING' check(request_status in ('PENDING','APPROVED','REJECTED','CANCELLED')),review_note varchar(1000),reviewed_by_staff_id bigint references staff_account(id) on delete set null,reviewed_at timestamptz,created_by_staff_id bigint references staff_account(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(end_date>=start_date),check((request_status in ('PENDING','CANCELLED') and reviewed_at is null) or (request_status in ('APPROVED','REJECTED') and reviewed_at is not null)));
create index idx_hr_leave_employee_dates on hr_leave_request(employee_id,start_date,end_date);
create index idx_hr_leave_status_created on hr_leave_request(request_status,created_at desc);
insert into staff_permission_catalog(permission_key,display_name,description) values ('HR_ATTENDANCE_VIEW','View attendance','View attendance records and summaries.'),('HR_ATTENDANCE_MANAGE','Manage attendance','Record and correct daily attendance.'),('HR_LEAVE_VIEW','View leave requests','View leave types and employee leave requests.'),('HR_LEAVE_MANAGE','Manage leave','Submit, approve or reject employee leave requests.') on conflict(permission_key) do update set display_name=excluded.display_name,description=excluded.description;